from pathlib import Path
import re

ROOT = Path('.')
renderer_path = ROOT / 'src/map/ormap_renderer.c'
header_path = ROOT / 'src/map/ormap_renderer.h'
main_path = ROOT / 'src/main.c'

renderer = renderer_path.read_text()
header = header_path.read_text()
main = main_path.read_text()


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, got {count}')
    return text.replace(old, new, 1)


def regex_once(text, pattern, repl, label):
    new, count = re.subn(pattern, repl, text, count=1, flags=re.S)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one regex match, got {count}')
    return new

# ---------------------------------------------------------------------------
# Public/runtime state + DEV counters.
# ---------------------------------------------------------------------------
header = replace_once(
    header,
    '''typedef struct OpenRideORMapAreaDebugStats {\n    double areas_ms;\n    double load_ms;\n    uint32_t tiles_visited;\n    uint32_t triangles_drawn;\n    uint32_t batches;\n    uint32_t mask_prewarm_loads;\n} OpenRideORMapAreaDebugStats;''',
    '''typedef struct OpenRideORMapAreaDebugStats {\n    double areas_ms;\n    double load_ms;\n    uint32_t tiles_visited;\n    uint32_t triangles_drawn;\n    uint32_t batches;\n    uint32_t prewarm_loads;\n    uint32_t draw_loads;\n    uint32_t deferred_loads;\n} OpenRideORMapAreaDebugStats;''',
    'area debug stats')

header = replace_once(
    header,
    '''    uint32_t road_draw_load_budget_remaining;\n    bool road_debug_active;\n    bool area_debug_active;''',
    '''    uint32_t road_draw_load_budget_remaining;\n    uint32_t area_draw_load_budget_remaining;\n    bool road_debug_active;\n    bool area_debug_active;\n    bool area_detail_ready;''',
    'renderer area budget state')

# ---------------------------------------------------------------------------
# LOD/load budgets. One speculative mask + one detail area tile per frame keeps
# synchronous work bounded; the coarse representation remains the fallback.
# ---------------------------------------------------------------------------
renderer = replace_once(
    renderer,
    '''#define ORMAP_ROAD_PREWARM_TILE_BUDGET 3U\n#define ORMAP_ROAD_DRAW_LOAD_BUDGET 2U\n#define ORMAP_BUILTUP_MASK_PREWARM_TILE_BUDGET 6U\n#define ORMAP_BUILTUP_PREWARM_START 12.20\n#define ORMAP_BUILTUP_OVERVIEW_START 13.15\n#define ORMAP_BUILTUP_OVERVIEW_FULL 13.35\n#define ORMAP_BUILTUP_DETAIL_START 14.00\n#define ORMAP_BUILTUP_DETAIL_END 14.55''',
    '''#define ORMAP_ROAD_PREWARM_TILE_BUDGET 3U\n#define ORMAP_ROAD_DRAW_LOAD_BUDGET 2U\n#define ORMAP_AREA_PREWARM_TILE_BUDGET 1U\n#define ORMAP_AREA_DRAW_LOAD_BUDGET 1U\n#define ORMAP_BUILTUP_MASK_PREWARM_TILE_BUDGET 1U\n#define ORMAP_BUILTUP_PREWARM_START 11.80\n#define ORMAP_BUILTUP_OVERVIEW_START 13.15\n#define ORMAP_BUILTUP_OVERVIEW_FULL 13.35\n#define ORMAP_BUILTUP_DETAIL_START 14.00\n#define ORMAP_BUILTUP_DETAIL_END 14.55\n#define ORMAP_WATER_DETAIL_PREWARM_START 11.00\n#define ORMAP_WATER_DETAIL_START 13.40\n#define ORMAP_WATER_DETAIL_END 14.20''',
    'area progressive constants')

# ---------------------------------------------------------------------------
# Mask cache: progressive prewarm and one unexpected synchronous draw load max.
# ---------------------------------------------------------------------------
renderer = regex_once(
    renderer,
    r'''static OpenRideORMapMaskCacheEntry \*mask_cache_slot\(OpenRideORMapRenderer \*renderer,\n                                                     int zoom,\n                                                     int x,\n                                                     int y\)\n\{.*?\n\}\n\nstatic uint32_t prewarm_mask_level''',
    '''static OpenRideORMapMaskCacheEntry *mask_cache_slot(OpenRideORMapRenderer *renderer,\n                                                     int zoom,\n                                                     int x,\n                                                     int y,\n                                                     bool prewarm,\n                                                     bool budgeted_draw_load)\n{\n    const size_t base = tile_cache_set_base(OPENRIDE_ORMAP_MASK_CACHE_CAPACITY,\n                                            zoom, x, y);\n    OpenRideORMapMaskCacheEntry *victim = NULL;\n    OpenRideORMapMaskCacheEntry *oldest = &renderer->masks[base];\n    for (size_t i = 0U; i < ORMAP_CACHE_ASSOCIATIVITY; ++i) {\n        OpenRideORMapMaskCacheEntry *entry = &renderer->masks[base + i];\n        if (entry->occupied && entry->zoom == zoom && entry->x == x && entry->y == y) {\n            entry->last_used = renderer->frame_counter;\n            return entry;\n        }\n        if (!entry->occupied && !victim) victim = entry;\n        if (entry->occupied && oldest->occupied && entry->last_used < oldest->last_used) {\n            oldest = entry;\n        }\n    }\n\n    if (budgeted_draw_load && !prewarm) {\n        if (renderer->area_draw_load_budget_remaining == 0U) {\n            ++renderer->area_debug.deferred_loads;\n            return NULL;\n        }\n        --renderer->area_draw_load_budget_remaining;\n    }\n\n    if (!victim) {\n        victim = oldest;\n        if (prewarm && victim->occupied\n            && victim->last_used + 1U >= renderer->frame_counter) {\n            return NULL;\n        }\n    }\n    if (victim->occupied) openride_ormap_mask_tile_destroy(&victim->tile);\n    memset(victim, 0, sizeof(*victim));\n    victim->occupied = true;\n    victim->zoom = zoom;\n    victim->x = x;\n    victim->y = y;\n    victim->last_used = renderer->frame_counter;\n    const uint64_t load_started = SDL_GetTicksNS();\n    char error[160] = {0};\n    if (!openride_ormap_load_mask_tile(renderer->map,\n                                       zoom,\n                                       x,\n                                       y,\n                                       &victim->tile,\n                                       error,\n                                       sizeof(error))) {\n        /* Missing mask tile is expected in rural areas. */\n    }\n    if (renderer->area_debug_active) {\n        renderer->area_debug.load_ms +=\n            (double)(SDL_GetTicksNS() - load_started) / 1000000.0;\n        if (prewarm) ++renderer->area_debug.prewarm_loads;\n        else ++renderer->area_debug.draw_loads;\n    }\n    return victim;\n}\n\nstatic uint32_t prewarm_mask_level''',
    'mask cache slot')

renderer = replace_once(
    renderer,
    '''            if (mask_cache_contains(renderer, zoom, qx, ty)) continue;\n            if (!mask_cache_slot(renderer, zoom, qx, ty)) continue;\n            ++renderer->area_debug.mask_prewarm_loads;\n            if (++loaded >= budget) return loaded;''',
    '''            if (mask_cache_contains(renderer, zoom, qx, ty)) continue;\n            if (!mask_cache_slot(renderer, zoom, qx, ty, true, false)) continue;\n            if (++loaded >= budget) return loaded;''',
    'mask prewarm call')

# Insert a readiness test after mask prewarm. Missing/empty tiles count as ready
# once an occupied cache entry has recorded that lookup.
mask_ready_marker = '''    return loaded;\n}\n\nstatic OpenRideORMapWaterCacheEntry *water_cache_slot'''
mask_ready_replacement = '''    return loaded;\n}\n\nstatic bool mask_level_cache_ready(const OpenRideORMapRenderer *renderer,\n                                   const OpenRideMapCamera *camera,\n                                   int width,\n                                   int height,\n                                   int zoom)\n{\n    if (!renderer || !camera) return false;\n    const int count = 1 << zoom;\n    const double scale = pow(2.0, camera->zoom - zoom);\n    const double tile_size = ORMAP_TILE_SIZE * scale;\n    const OpenRidePointD center =\n        openride_mercator_forward(camera->center_lat, camera->center_lon);\n    const double world_size = tile_size * count;\n    const double center_x = center.x * world_size;\n    const double center_y = center.y * world_size;\n    const double bearing =\n        camera->bearing_deg * 3.14159265358979323846 / 180.0;\n    const double half_w = fabs(cos(bearing)) * width * 0.5\n        + fabs(sin(bearing)) * height * 0.5;\n    const double half_h = fabs(sin(bearing)) * width * 0.5\n        + fabs(cos(bearing)) * height * 0.5;\n    const int first_x = (int)floor((center_x - half_w) / tile_size);\n    const int last_x = (int)floor((center_x + half_w) / tile_size);\n    const int first_y = (int)floor((center_y - half_h) / tile_size);\n    const int last_y = (int)floor((center_y + half_h) / tile_size);\n\n    for (int ty = first_y; ty <= last_y; ++ty) {\n        if (ty < 0 || ty >= count) continue;\n        for (int tx = first_x; tx <= last_x; ++tx) {\n            if (!mask_cache_contains(renderer, zoom, wrap_x(tx, count), ty)) {\n                return false;\n            }\n        }\n    }\n    return true;\n}\n\nstatic OpenRideORMapWaterCacheEntry *water_cache_slot'''
renderer = replace_once(renderer, mask_ready_marker, mask_ready_replacement,
                        'mask cache readiness')

# ---------------------------------------------------------------------------
# Area detail cache: same progressive policy + future-viewport prewarm.
# ---------------------------------------------------------------------------
renderer = regex_once(
    renderer,
    r'''static OpenRideORMapAreaCacheEntry \*area_cache_slot\(OpenRideORMapRenderer \*renderer,\n                                                     int zoom,\n                                                     int x,\n                                                     int y\)\n\{.*?\n\}\n\nstatic bool geometry_batch_rotated_rect''',
    '''static bool area_cache_contains(const OpenRideORMapRenderer *renderer,\n                                int zoom,\n                                int x,\n                                int y)\n{\n    if (!renderer) return false;\n    const size_t base = tile_cache_set_base(OPENRIDE_ORMAP_AREA_CACHE_CAPACITY,\n                                            zoom, x, y);\n    for (size_t i = 0U; i < ORMAP_CACHE_ASSOCIATIVITY; ++i) {\n        const OpenRideORMapAreaCacheEntry *entry = &renderer->areas[base + i];\n        if (entry->occupied && entry->zoom == zoom && entry->x == x && entry->y == y) {\n            return true;\n        }\n    }\n    return false;\n}\n\nstatic OpenRideORMapAreaCacheEntry *area_cache_slot(OpenRideORMapRenderer *renderer,\n                                                     int zoom,\n                                                     int x,\n                                                     int y,\n                                                     bool prewarm,\n                                                     bool budgeted_draw_load)\n{\n    const size_t base = tile_cache_set_base(OPENRIDE_ORMAP_AREA_CACHE_CAPACITY,\n                                            zoom, x, y);\n    OpenRideORMapAreaCacheEntry *victim = NULL;\n    OpenRideORMapAreaCacheEntry *oldest = &renderer->areas[base];\n    for (size_t i = 0U; i < ORMAP_CACHE_ASSOCIATIVITY; ++i) {\n        OpenRideORMapAreaCacheEntry *entry = &renderer->areas[base + i];\n        if (entry->occupied && entry->zoom == zoom && entry->x == x && entry->y == y) {\n            entry->last_used = renderer->frame_counter;\n            return entry;\n        }\n        if (!entry->occupied && !victim) victim = entry;\n        if (entry->occupied && oldest->occupied && entry->last_used < oldest->last_used) {\n            oldest = entry;\n        }\n    }\n\n    if (budgeted_draw_load && !prewarm) {\n        if (renderer->area_draw_load_budget_remaining == 0U) {\n            ++renderer->area_debug.deferred_loads;\n            return NULL;\n        }\n        --renderer->area_draw_load_budget_remaining;\n    }\n\n    if (!victim) {\n        victim = oldest;\n        if (prewarm && victim->occupied\n            && victim->last_used + 1U >= renderer->frame_counter) {\n            return NULL;\n        }\n    }\n    if (victim->occupied) openride_ormap_area_tile_destroy(&victim->tile);\n    memset(victim, 0, sizeof(*victim));\n    victim->occupied = true;\n    victim->zoom = zoom;\n    victim->x = x;\n    victim->y = y;\n    victim->last_used = renderer->frame_counter;\n    const uint64_t load_started = SDL_GetTicksNS();\n    char error[160] = {0};\n    if (!openride_ormap_load_area_tile(renderer->map,\n                                       zoom,\n                                       x,\n                                       y,\n                                       &victim->tile,\n                                       error,\n                                       sizeof(error))) {\n        /* Missing vector area tiles are common over rural/empty regions. */\n    }\n    if (renderer->area_debug_active) {\n        renderer->area_debug.load_ms +=\n            (double)(SDL_GetTicksNS() - load_started) / 1000000.0;\n        if (prewarm) ++renderer->area_debug.prewarm_loads;\n        else ++renderer->area_debug.draw_loads;\n    }\n    return victim;\n}\n\nstatic uint32_t prewarm_area_level(OpenRideORMapRenderer *renderer,\n                                   const OpenRideMapCamera *camera,\n                                   int width,\n                                   int height,\n                                   int zoom,\n                                   double viewport_zoom,\n                                   uint32_t budget)\n{\n    if (!renderer || !camera || budget == 0U) return 0U;\n    const int count = 1 << zoom;\n    const double scale = pow(2.0, viewport_zoom - zoom);\n    const double tile_size = ORMAP_TILE_SIZE * scale;\n    const OpenRidePointD center =\n        openride_mercator_forward(camera->center_lat, camera->center_lon);\n    const double world_size = tile_size * count;\n    const double center_x = center.x * world_size;\n    const double center_y = center.y * world_size;\n    const double bearing =\n        camera->bearing_deg * 3.14159265358979323846 / 180.0;\n    const double half_w = fabs(cos(bearing)) * width * 0.5\n        + fabs(sin(bearing)) * height * 0.5;\n    const double half_h = fabs(sin(bearing)) * width * 0.5\n        + fabs(cos(bearing)) * height * 0.5;\n    const int first_x = (int)floor((center_x - half_w) / tile_size);\n    const int last_x = (int)floor((center_x + half_w) / tile_size);\n    const int first_y = (int)floor((center_y - half_h) / tile_size);\n    const int last_y = (int)floor((center_y + half_h) / tile_size);\n\n    uint32_t loaded = 0U;\n    for (int ty = first_y; ty <= last_y; ++ty) {\n        if (ty < 0 || ty >= count) continue;\n        for (int tx = first_x; tx <= last_x; ++tx) {\n            const int qx = wrap_x(tx, count);\n            if (area_cache_contains(renderer, zoom, qx, ty)) continue;\n            if (!area_cache_slot(renderer, zoom, qx, ty, true, false)) continue;\n            if (++loaded >= budget) return loaded;\n        }\n    }\n    return loaded;\n}\n\nstatic bool area_level_cache_ready(const OpenRideORMapRenderer *renderer,\n                                   const OpenRideMapCamera *camera,\n                                   int width,\n                                   int height,\n                                   int zoom)\n{\n    if (!renderer || !camera) return false;\n    const int count = 1 << zoom;\n    const double scale = pow(2.0, camera->zoom - zoom);\n    const double tile_size = ORMAP_TILE_SIZE * scale;\n    const OpenRidePointD center =\n        openride_mercator_forward(camera->center_lat, camera->center_lon);\n    const double world_size = tile_size * count;\n    const double center_x = center.x * world_size;\n    const double center_y = center.y * world_size;\n    const double bearing =\n        camera->bearing_deg * 3.14159265358979323846 / 180.0;\n    const double half_w = fabs(cos(bearing)) * width * 0.5\n        + fabs(sin(bearing)) * height * 0.5;\n    const double half_h = fabs(sin(bearing)) * width * 0.5\n        + fabs(cos(bearing)) * height * 0.5;\n    const int first_x = (int)floor((center_x - half_w) / tile_size);\n    const int last_x = (int)floor((center_x + half_w) / tile_size);\n    const int first_y = (int)floor((center_y - half_h) / tile_size);\n    const int last_y = (int)floor((center_y + half_h) / tile_size);\n\n    for (int ty = first_y; ty <= last_y; ++ty) {\n        if (ty < 0 || ty >= count) continue;\n        for (int tx = first_x; tx <= last_x; ++tx) {\n            if (!area_cache_contains(renderer, zoom, wrap_x(tx, count), ty)) {\n                return false;\n            }\n        }\n    }\n    return true;\n}\n\nstatic bool geometry_batch_rotated_rect''',
    'area cache progressive block')

# ---------------------------------------------------------------------------
# Surface preparation happens in the first surface layer (masks). This means
# the following Areas layer sees a stable readiness decision in the same frame.
# ---------------------------------------------------------------------------
renderer = replace_once(
    renderer,
    '''    const double forest_start = v4 ? 13.40 : 14.0;\n    const double forest_end = v4 ? 14.40 : 14.50;\n    const int zoom = metadata ? metadata->mask_zoom : OPENRIDE_ORMAP_MASK_ZOOM;\n\n    if (v6\n        && camera->zoom >= ORMAP_BUILTUP_PREWARM_START\n        && camera->zoom < ORMAP_BUILTUP_OVERVIEW_FULL) {''',
    '''    const double forest_start = v4 ? 13.40 : 14.0;\n    const double forest_end = v4 ? 14.40 : 14.50;\n    const int zoom = metadata ? metadata->mask_zoom : OPENRIDE_ORMAP_MASK_ZOOM;\n\n    if (v6\n        && camera->zoom >= ORMAP_WATER_DETAIL_PREWARM_START\n        && metadata->area_detail_zoom >= 0) {\n        const double detail_view_zoom =\n            camera->zoom < ORMAP_WATER_DETAIL_START\n                ? ORMAP_WATER_DETAIL_START\n                : camera->zoom;\n        (void)prewarm_area_level(renderer,\n                                 camera,\n                                 width,\n                                 height,\n                                 metadata->area_detail_zoom,\n                                 detail_view_zoom,\n                                 ORMAP_AREA_PREWARM_TILE_BUDGET);\n        renderer->area_detail_ready = area_level_cache_ready(renderer,\n                                                              camera,\n                                                              width,\n                                                              height,\n                                                              metadata->area_detail_zoom);\n    }\n\n    if (v6\n        && camera->zoom >= ORMAP_BUILTUP_PREWARM_START\n        && camera->zoom < ORMAP_BUILTUP_OVERVIEW_FULL) {''',
    'surface prewarm in mask layer')

renderer = replace_once(
    renderer,
    '''    const double builtup_overview_fade = v6\n        ? ormap_zoom_smoothstep(camera->zoom,\n                                ORMAP_BUILTUP_OVERVIEW_START,\n                                ORMAP_BUILTUP_OVERVIEW_FULL)\n            * (1.0 - ormap_zoom_smoothstep(camera->zoom,\n                                           ORMAP_BUILTUP_DETAIL_START,\n                                           ORMAP_BUILTUP_DETAIL_END))\n        : 0.0;''',
    '''    const bool builtup_overview_ready =\n        !v6 || mask_level_cache_ready(renderer, camera, width, height, zoom);\n    const double builtup_detail_handoff =\n        v6 && renderer->area_detail_ready\n            ? ormap_zoom_smoothstep(camera->zoom,\n                                    ORMAP_BUILTUP_DETAIL_START,\n                                    ORMAP_BUILTUP_DETAIL_END)\n            : 0.0;\n    const double builtup_overview_fade =\n        v6 && builtup_overview_ready\n            ? ormap_zoom_smoothstep(camera->zoom,\n                                    ORMAP_BUILTUP_OVERVIEW_START,\n                                    ORMAP_BUILTUP_OVERVIEW_FULL)\n                * (1.0 - builtup_detail_handoff)\n            : 0.0;''',
    'builtup readiness fade')

renderer = renderer.replace(
    'mask_cache_slot(renderer, zoom, qx, ty);',
    'mask_cache_slot(renderer, zoom, qx, ty, false, true);')

# ---------------------------------------------------------------------------
# Area draw path: detail misses are budgeted. v6 water keeps coarse geometry
# until the future detail viewport is fully cached, then fades 13.40 -> 14.20.
# ---------------------------------------------------------------------------
renderer = replace_once(
    renderer,
    '''static void draw_area_level(OpenRideORMapRenderer *renderer,\n                            const OpenRideMapCamera *camera,\n                            int width,\n                            int height,\n                            int zoom,\n                            bool draw_builtup,\n                            bool draw_water,\n                            double level_fade)''',
    '''static void draw_area_level(OpenRideORMapRenderer *renderer,\n                            const OpenRideMapCamera *camera,\n                            int width,\n                            int height,\n                            int zoom,\n                            bool draw_builtup,\n                            bool draw_water,\n                            double level_fade,\n                            bool budgeted_draw_load)''',
    'draw area signature')

renderer = replace_once(
    renderer,
    'OpenRideORMapAreaCacheEntry *entry = area_cache_slot(renderer, zoom, qx, ty);',
    'OpenRideORMapAreaCacheEntry *entry = area_cache_slot(renderer, zoom, qx, ty, false, budgeted_draw_load);',
    'draw area cache call')

old_draw_areas = '''    const OpenRideORMapMetadata *metadata = openride_ormap_metadata(renderer->map);\n    if (metadata && metadata->format_version >= 3 && camera->zoom >= 10.0) {\n        const double detail_mix =\n            ormap_zoom_smoothstep(camera->zoom, 12.15, 12.85);\n        const bool v6 = metadata->format_version >= 6;\n        const bool draw_detail_builtup =\n            camera->zoom >= (v6 ? ORMAP_BUILTUP_DETAIL_START : 13.0);\n\n        if (detail_mix < 1.0) {\n            draw_area_level(renderer,\n                            camera,\n                            width,\n                            height,\n                            metadata->area_coarse_zoom,\n                            false,\n                            true,\n                            1.0 - detail_mix);\n        }\n        if (detail_mix > 0.0) {\n            draw_area_level(renderer,\n                            camera,\n                            width,\n                            height,\n                            metadata->area_detail_zoom,\n                            draw_detail_builtup,\n                            true,\n                            detail_mix);\n        }\n    }'''
new_draw_areas = '''    const OpenRideORMapMetadata *metadata = openride_ormap_metadata(renderer->map);\n    if (metadata && metadata->format_version >= 3 && camera->zoom >= 10.0) {\n        const bool v6 = metadata->format_version >= 6;\n        if (v6) {\n            if (!renderer->area_detail_ready\n                && camera->zoom >= ORMAP_WATER_DETAIL_PREWARM_START) {\n                const double detail_view_zoom =\n                    camera->zoom < ORMAP_WATER_DETAIL_START\n                        ? ORMAP_WATER_DETAIL_START\n                        : camera->zoom;\n                (void)prewarm_area_level(renderer,\n                                         camera,\n                                         width,\n                                         height,\n                                         metadata->area_detail_zoom,\n                                         detail_view_zoom,\n                                         ORMAP_AREA_PREWARM_TILE_BUDGET);\n                renderer->area_detail_ready = area_level_cache_ready(renderer,\n                                                                      camera,\n                                                                      width,\n                                                                      height,\n                                                                      metadata->area_detail_zoom);\n            }\n\n            const double nominal_detail_mix =\n                ormap_zoom_smoothstep(camera->zoom,\n                                      ORMAP_WATER_DETAIL_START,\n                                      ORMAP_WATER_DETAIL_END);\n            const double detail_mix =\n                renderer->area_detail_ready ? nominal_detail_mix : 0.0;\n            const bool draw_detail_builtup =\n                renderer->area_detail_ready\n                && camera->zoom >= ORMAP_BUILTUP_DETAIL_START;\n\n            if (detail_mix < 1.0) {\n                draw_area_level(renderer,\n                                camera,\n                                width,\n                                height,\n                                metadata->area_coarse_zoom,\n                                false,\n                                true,\n                                1.0 - detail_mix,\n                                false);\n            }\n            if (detail_mix > 0.0) {\n                draw_area_level(renderer,\n                                camera,\n                                width,\n                                height,\n                                metadata->area_detail_zoom,\n                                draw_detail_builtup,\n                                true,\n                                detail_mix,\n                                true);\n            }\n        } else {\n            const double detail_mix =\n                ormap_zoom_smoothstep(camera->zoom, 12.15, 12.85);\n            const bool draw_detail_builtup = camera->zoom >= 13.0;\n            if (detail_mix < 1.0) {\n                draw_area_level(renderer,\n                                camera,\n                                width,\n                                height,\n                                metadata->area_coarse_zoom,\n                                false,\n                                true,\n                                1.0 - detail_mix,\n                                false);\n            }\n            if (detail_mix > 0.0) {\n                draw_area_level(renderer,\n                                camera,\n                                width,\n                                height,\n                                metadata->area_detail_zoom,\n                                draw_detail_builtup,\n                                true,\n                                detail_mix,\n                                false);\n            }\n        }\n    }'''
renderer = replace_once(renderer, old_draw_areas, new_draw_areas,
                        'draw areas progressive handoff')

# ---------------------------------------------------------------------------
# Per-frame state/budget reset.
# ---------------------------------------------------------------------------
renderer = replace_once(
    renderer,
    '''    renderer->road_debug.prewarm_zoom = -1;\n    renderer->road_draw_load_budget_remaining = ORMAP_ROAD_DRAW_LOAD_BUDGET;\n    renderer->road_debug_active = false;''',
    '''    renderer->road_debug.prewarm_zoom = -1;\n    renderer->road_draw_load_budget_remaining = ORMAP_ROAD_DRAW_LOAD_BUDGET;\n    renderer->area_draw_load_budget_remaining = ORMAP_AREA_DRAW_LOAD_BUDGET;\n    renderer->road_debug_active = false;\n    renderer->area_debug_active = false;\n    renderer->area_detail_ready = false;''',
    'begin frame area budget')

# ---------------------------------------------------------------------------
# Compact HUD: preserve A/AL/AT/AG/AB and add total prewarm/draw/deferred loads.
# ---------------------------------------------------------------------------
main = replace_once(
    main,
    '''                     "A %.1fms AL%.1f AT%u AG%u AB%u AP%u",\n                     area_debug.areas_ms,\n                     area_debug.load_ms,\n                     area_debug.tiles_visited,\n                     area_debug.triangles_drawn,\n                     area_debug.batches,\n                     area_debug.mask_prewarm_loads);''',
    '''                     "A%.1f L%.1f T%u G%u B%u P%u D%u X%u",\n                     area_debug.areas_ms,\n                     area_debug.load_ms,\n                     area_debug.tiles_visited,\n                     area_debug.triangles_drawn,\n                     area_debug.batches,\n                     area_debug.prewarm_loads,\n                     area_debug.draw_loads,\n                     area_debug.deferred_loads);''',
    'area HUD counters')

renderer_path.write_text(renderer)
header_path.write_text(header)
main_path.write_text(main)
